void checkTemperature(int temperature, int setTemperature, int overTempValue, int overTempLimit) {
    int LO = setTemperature - overTempValue;
    int UO = setTemperature + overTempValue;

    if (temperature > LO && temperature < UO) {
        // Temperature is within the set temperature range
        std::cout << "Temperature is within the set temperature range.";
    } else if (temperature <= LO) {
        // Temperature is lower than the lower limit
        std::cout << "Temperature is lower than the lower limit.";
    } else if (temperature >= UO) {
        // Temperature is higher than the upper limit
        std::cout << "Temperature is higher than the upper limit.";
    } else {
        // Temperature is within the over temperature limit
        std::cout << "Temperature limit has been exceeded.";
    }
}

void checkConditions(int TSET, int TD, int T, int UT, int LO, int LT, int UO) {
  if (T < LT) {
    // The current temperature is below the lower trigger value
    processRequest(TSET, TD, T, UT, LO, LT, UO);
  } else if (T > UO) {
    // The current temperature is above the upper trigger value
    processRequest(TSET, TD, T, UT, LO, LT, UO);
  } else {
    // The current temperature is within the range of the lower and upper trigger values
    if (T < TSET) {
      // The current temperature is below the set temperature
      processRequest(TSET, TD, T, UT, LO, LT, UO);
    } else {
      // The current temperature is above the set temperature
      processRequest(TSET, TD, T, UT, LO, LT, UO);
    }
  }
}

void processRequest(int TSET, int TD, int T, int UT, int LO, int LT, int UO) {
  if (T < LT) {
    // The current temperature is below the lower trigger value
    processRequest(TSET, TD, T, UT, LO, LT, UO);
  } else if (T > UO) {
    // The current temperature is above the upper trigger value
    processRequest(TSET, TD, T, UT, LO, LT, UO);
  } else {
    // The current temperature is within the range of the lower and upper trigger values
    if (T < TSET) {
      // The current temperature is below the set temperature
      processRequest(TSET, TD, T, UT, LO, LT, UO);
    } else {
      // The current temperature is above the set temperature
      processRequest(TSET, TD, T, UT, LO, LT, UO);
    }
  }
}

void processRequest(int unitType, bool isOn) {
    // Check if the maximum number of heating or cooling units is already running
    if (maxUnitsRunning[unitType]) {
        // Add the request to the LIFO queue
        if (queue[unitType].empty()) {
            queue[unitType].push(request);
        } else {
            queue[unitType].push(queue[unitType].front());
            queue[unitType].pop();
        }
    } else {
        // Generate a request to turn on the requested unit
        request = { unitType, isOn: true };
        // Check the queue of waiting requests
        checkQueue(unitType);
        // Turn on the unit if the thermostat still needs it turned on
        if (thermostat[unitType].isOn && !thermostat[unitType].isOn) {
            turnOnUnit(unitType);
        }
    }
}

void processQueue(int unitType) {
    if (queue[unitType].empty()) {
     return;
    } else {
     request = queue[unitType].front();
      queue[unitType].pop();
     checkQueue(unitType);
      if (thermostat[unitType].isOn && !thermostat[unitType].isOn) {
       turnOnUnit(unitType);
     }
    }
}

void checkQueue(int unitType) {
    while (!queue[unitType].empty()) {
     request = queue[unitType].front();
      queue[unitType].pop();
      // Check if the request can be fulfilled
      // If the request can be fulfilled, remove the request from the queue and check the next request
      // If the next request cannot be fulfilled, return to the previous request and continue to check the next request
      // If the queue is empty, return without doing anything
    }
}

void turnOnUnit(int unitType) {
  // Check if the maximum number of heating or cooling units is already running
  if (maxUnitsRunning[unitType]) {
    // Add the request to the LIFO queue
    if (queue[unitType].empty()) {
      queue[unitType].push(request);
    } else {
      queue[unitType].push(queue[unitType] .front());
      queue[unitType].pop();
    }
  } else {
    // Generate a request to turn on the requested unit
    request = { unitType, isOn: true };
    // Check the queue of waiting requests
    checkQueue(unitType);
    // Turn on the unit if the thermostat still needs it turned on
    if (thermostat[unitType].isOn && !thermostat[unitType].isOn) {
      turnOnUnit(unitType);
    }
  }
}

